window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4143f759f4069d9a"]={"versions": [{"id": "FIG-4143f759f4069d9a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm mit Service-Interface-Spezifikation (AUTOSAR Adaptive Platform Modellierung).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (R21-11), Functional Cluster <em>Update and Configuration Management (UCM)</em> in Interaktion mit <em>State Management (SM)</em>.</li>\n<li><strong>Technischer Zweck:</strong> Entkopplung der Update-Orchestrierung von der Systemzustandskontrolle. Das UCM (hier in der Rolle des <em>UCM Subordinate</em>) führt Software-Updates nicht eigenmächtig auf Prozessebene aus, sondern steuert den Lebenszyklus und die Ausführungsmodi der Machine über das servicifizierte Interface <code>UpdateRequest</code>, welches vom <em>State Management</em> bereitgestellt wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Komponenten:</strong></li>\n<li><code>UCM Subordinate</code>: Adaptive Application / Functional Cluster Component; agiert als Service-Consumer (Client) für Update-Abläufe auf Maschinenebene.</li>\n<li><code>State Management</code> (<code>«aapFunctionalCluster»</code>, Ausprägung: <code>daemon-based</code>): Zentraler System-Daemon zur Koordination von Funktionsgruppen (<code>FunctionGroupState</code>), Maschinenmodi und Prozess-Lebenszyklen; agiert als Service-Provider (Server).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Ports & Bindungen:</strong></li>\n<li>Client-Port: <code>«aapRequiredPort»</code> an <code>UCM Subordinate</code> mit Abhängigkeitsbeziehung (<code>«use»</code>) auf das Service-Interface.</li>\n<li>Server-Port: <code>«aapProvidedPort»</code> an <code>State Management</code> mit Realisierungsbeziehung (Interface-Implementierung).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Service Interface <code>UpdateRequest</code>:</strong></li>\n<li>Stereotypen: <code>«aapAraComServiceInterface»</code>, <code>«aapInterface»</code>. Bindung erfolgt über die IPC-Transportschicht von <code>ara::com</code>.</li>\n<li>Methodenspezifische Stereotypen: <code>«aapAccessControlled»</code> (Absicherung über Identity and Access Management / IAM), <code>«aapServiceMethod»</code>.</li>\n<li>Methoden:</li>\n<li><code>RequestUpdateSession()</code>: Beantragt die exklusive Berechtigung zur Durchführung einer Update-Sitzung beim State Management.</li>\n<li><code>PrepareUpdate()</code>: Weist SM an, betroffene <code>FunctionGroups</code> bzw. Software-Cluster in einen update-fähigen Ruhezustand zu überführen.</li>\n<li><code>VerifyUpdate()</code>: Beauftragt SM mit der Funktions- und Integritätsprüfung nach Aktivierung des neuen Softwarestands.</li>\n<li><code>PrepareRollback()</code>: Signalisiert SM die Einleitung der Rückfallebene bei fehlgeschlagener Verifikation oder Update-Abbruch.</li>\n<li><code>ResetMachine()</code>: Fordert einen deterministischen Warmstart/Reboot der Machine an, um neue Partitionen/Softwarestände über das Execution Management zu mounten/starten.</li>\n<li><code>StopUpdateSession()</code>: Beendet die Update-Sitzung und versetzt die Machine zurück in den regulären Betriebsmodus.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Session-Initialisierung (Trigger: Eingehendes Software-Paket):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>UCM Subordinate</code> ruft synchron/asynchron <code>RequestUpdateSession()</code> via <code>ara::com</code>.</li>\n<li><em>State Management</em> prüft globale System-Preconditions (z. B. Fahrzeugstillstand, Klemmenstatus, Diagnosemodus) und quittiert oder verweigert die Sitzung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung (Staging Phase):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Transfer/Extrahieren der Software-Cluster ruft UCM <code>PrepareUpdate()</code>.</li>\n<li>SM stoppt bzw. degradiert abhängige Applikationsprozesse über das <em>Execution Management</em> (<code>ara::exec</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Neustart:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Vorbereitung triggert UCM <code>ResetMachine()</code>.</li>\n<li>SM initiiert den kontrollierten Machine-State-Wechsel (Reboot/Shutdown).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verifikation & Abschluss / Rollback:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach dem Hochlauf veranlasst UCM über <code>VerifyUpdate()</code> die Verifikationsphase.</li>\n<li><em>Erfolgspfad:</em> SM meldet stabile Prozesszustände; UCM ruft <code>StopUpdateSession()</code>, womit die neue Version persistent geschaltet wird.</li>\n<li><em>Fehlerpfad:</em> Timeout oder Fehlfunktion; UCM initiiert <code>PrepareRollback()</code>, gefolgt von <code>ResetMachine()</code>, um den vorherigen Softwarestand zu reaktivieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Access Control & IAM (SWS / Manifeste):</strong> Da das Interface mit <code>«aapAccessControlled»</code> annotiert ist, muss im <em>Service Instance Manifest</em> und <em>Execution Manifest</em> ein entsprechendes <code>Grant</code> für den UCM-Prozess konfiguriert sein. Nicht autorisierte Aufrufe werden vom <code>ara::com</code>/IAM-Layer mit Security-Fehlern abgewiesen.</li>\n<li><strong>Plattform-Zustandsverantwortung:</strong> Applikations- und UCM-Entwickler dürfen keine direkten OS-Reboots (z. B. POSIX <code>reboot()</code>, <code>kill()</code>) aufrufen. Der Maschinenzustand darf ausschließlich deklarativ über SM und dessen Anbindung an <code>Execution Management</code> gewechselt werden.</li>\n<li><strong>Fehlerbehandlung (<code>ara::core::Result</code>):</strong> Sämtliche Methodenaufrufe erfordern robuste Auswertung von Rückgabecodes / Exceptions (insb. <code>UcmErrorDomain</code> bzw. <code>SmErrorDomain</code>). Ein Ablehnen von <code>RequestUpdateSession()</code> muss von UCM an das externe Diagnose- bzw. OTA-Backend propagiert werden (z. B. NRC <code>ConditionsNotCorrect</code>).</li>\n<li><strong>Daemon-Abhängigkeit:</strong> <code>State Management</code> läuft als nativer Plattform-Daemon. Startreihenfolgen und IPC-Verbindungsaufbau via <code>ara::com</code> müssen über das <em>Execution Manifest</em> so synchronisiert sein, dass <code>UpdateRequest</code> vor Beginn jeglicher UCM-Aktivitäten bindbar ist.</li>\n</ul>"}, {"id": "FIG-cb8823e6e5b28f91", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm mit Service-Interface-Spezifikation (AUTOSAR Adaptive Platform Modellierung).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (R21-11), Functional Cluster <em>Update and Configuration Management (UCM)</em> in Interaktion mit <em>State Management (SM)</em>.</li>\n<li><strong>Technischer Zweck:</strong> Entkopplung der Update-Orchestrierung von der Systemzustandskontrolle. Das UCM (hier in der Rolle des <em>UCM Subordinate</em>) führt Software-Updates nicht eigenmächtig auf Prozessebene aus, sondern steuert den Lebenszyklus und die Ausführungsmodi der Machine über das servicifizierte Interface <code>UpdateRequest</code>, welches vom <em>State Management</em> bereitgestellt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Komponenten:</strong></li>\n<li><code>UCM Subordinate</code>: Adaptive Application / Functional Cluster Component; agiert als Service-Consumer (Client) für Update-Abläufe auf Maschinenebene.</li>\n<li><code>State Management</code> (<code>«aapFunctionalCluster»</code>, Ausprägung: <code>daemon-based</code>): Zentraler System-Daemon zur Koordination von Funktionsgruppen (<code>FunctionGroupState</code>), Maschinenmodi und Prozess-Lebenszyklen; agiert als Service-Provider (Server).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Ports & Bindungen:</strong></li>\n<li>Client-Port: <code>«aapRequiredPort»</code> an <code>UCM Subordinate</code> mit Abhängigkeitsbeziehung (<code>«use»</code>) auf das Service-Interface.</li>\n<li>Server-Port: <code>«aapProvidedPort»</code> an <code>State Management</code> mit Realisierungsbeziehung (Interface-Implementierung).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Service Interface <code>UpdateRequest</code>:</strong></li>\n<li>Stereotypen: <code>«aapAraComServiceInterface»</code>, <code>«aapInterface»</code>. Bindung erfolgt über die IPC-Transportschicht von <code>ara::com</code>.</li>\n<li>Methodenspezifische Stereotypen: <code>«aapAccessControlled»</code> (Absicherung über Identity and Access Management / IAM), <code>«aapServiceMethod»</code>.</li>\n<li>Methoden:</li>\n<li><code>RequestUpdateSession()</code>: Beantragt die exklusive Berechtigung zur Durchführung einer Update-Sitzung beim State Management.</li>\n<li><code>PrepareUpdate()</code>: Weist SM an, betroffene <code>FunctionGroups</code> bzw. Software-Cluster in einen update-fähigen Ruhezustand zu überführen.</li>\n<li><code>VerifyUpdate()</code>: Beauftragt SM mit der Funktions- und Integritätsprüfung nach Aktivierung des neuen Softwarestands.</li>\n<li><code>PrepareRollback()</code>: Signalisiert SM die Einleitung der Rückfallebene bei fehlgeschlagener Verifikation oder Update-Abbruch.</li>\n<li><code>ResetMachine()</code>: Fordert einen deterministischen Warmstart/Reboot der Machine an, um neue Partitionen/Softwarestände über das Execution Management zu mounten/starten.</li>\n<li><code>StopUpdateSession()</code>: Beendet die Update-Sitzung und versetzt die Machine zurück in den regulären Betriebsmodus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Session-Initialisierung (Trigger: Eingehendes Software-Paket):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>UCM Subordinate</code> ruft synchron/asynchron <code>RequestUpdateSession()</code> via <code>ara::com</code>.</li>\n<li><em>State Management</em> prüft globale System-Preconditions (z. B. Fahrzeugstillstand, Klemmenstatus, Diagnosemodus) und quittiert oder verweigert die Sitzung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung (Staging Phase):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Transfer/Extrahieren der Software-Cluster ruft UCM <code>PrepareUpdate()</code>.</li>\n<li>SM stoppt bzw. degradiert abhängige Applikationsprozesse über das <em>Execution Management</em> (<code>ara::exec</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Neustart:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Vorbereitung triggert UCM <code>ResetMachine()</code>.</li>\n<li>SM initiiert den kontrollierten Machine-State-Wechsel (Reboot/Shutdown).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verifikation & Abschluss / Rollback:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach dem Hochlauf veranlasst UCM über <code>VerifyUpdate()</code> die Verifikationsphase.</li>\n<li><em>Erfolgspfad:</em> SM meldet stabile Prozesszustände; UCM ruft <code>StopUpdateSession()</code>, womit die neue Version persistent geschaltet wird.</li>\n<li><em>Fehlerpfad:</em> Timeout oder Fehlfunktion; UCM initiiert <code>PrepareRollback()</code>, gefolgt von <code>ResetMachine()</code>, um den vorherigen Softwarestand zu reaktivieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Access Control & IAM (SWS / Manifeste):</strong> Da das Interface mit <code>«aapAccessControlled»</code> annotiert ist, muss im <em>Service Instance Manifest</em> und <em>Execution Manifest</em> ein entsprechendes <code>Grant</code> für den UCM-Prozess konfiguriert sein. Nicht autorisierte Aufrufe werden vom <code>ara::com</code>/IAM-Layer mit Security-Fehlern abgewiesen.</li>\n<li><strong>Plattform-Zustandsverantwortung:</strong> Applikations- und UCM-Entwickler dürfen keine direkten OS-Reboots (z. B. POSIX <code>reboot()</code>, <code>kill()</code>) aufrufen. Der Maschinenzustand darf ausschließlich deklarativ über SM und dessen Anbindung an <code>Execution Management</code> gewechselt werden.</li>\n<li><strong>Fehlerbehandlung (<code>ara::core::Result</code>):</strong> Sämtliche Methodenaufrufe erfordern robuste Auswertung von Rückgabecodes / Exceptions (insb. <code>UcmErrorDomain</code> bzw. <code>SmErrorDomain</code>). Ein Ablehnen von <code>RequestUpdateSession()</code> muss von UCM an das externe Diagnose- bzw. OTA-Backend propagiert werden (z. B. NRC <code>ConditionsNotCorrect</code>).</li>\n<li><strong>Daemon-Abhängigkeit:</strong> <code>State Management</code> läuft als nativer Plattform-Daemon. Startreihenfolgen und IPC-Verbindungsaufbau via <code>ara::com</code> müssen über das <em>Execution Manifest</em> so synchronisiert sein, dass <code>UpdateRequest</code> vor Beginn jeglicher UCM-Aktivitäten bindbar ist.</li>\n</ul>"}, {"id": "FIG-eb368619d39cb66b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm mit Service-Interface-Spezifikation (AUTOSAR Adaptive Platform Modellierung).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (R21-11), Functional Cluster <em>Update and Configuration Management (UCM)</em> in Interaktion mit <em>State Management (SM)</em>.</li>\n<li><strong>Technischer Zweck:</strong> Entkopplung der Update-Orchestrierung von der Systemzustandskontrolle. Das UCM (hier in der Rolle des <em>UCM Subordinate</em>) führt Software-Updates nicht eigenmächtig auf Prozessebene aus, sondern steuert den Lebenszyklus und die Ausführungsmodi der Machine über das servicifizierte Interface <code>UpdateRequest</code>, welches vom <em>State Management</em> bereitgestellt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Komponenten:</strong></li>\n<li><code>Update and Configuration Management</code> (<code>«aapFunctionalCluster»</code>, Ausprägung: <code>daemon-based</code>): Zentraler Plattform-Daemon zur Koordination und Ausführung von Software- und Konfigurationsaktualisierungen; agiert als Service-Consumer (Client).</li>\n<li><code>State Management</code> (<code>«aapFunctionalCluster»</code>, Ausprägung: <code>daemon-based</code>): Zentraler System-Daemon zur Koordination von Funktionsgruppen (<code>FunctionGroupState</code>), Maschinenmodi und Prozess-Lebenszyklen; agiert als Service-Provider (Server).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Ports & Bindungen:</strong></li>\n<li>Client-Port: <code>«aapRequiredPort»</code> an <code>Update and Configuration Management</code> mit Abhängigkeitsbeziehung (<code>«use»</code>) auf das Service-Interface.</li>\n<li>Server-Port: <code>«aapProvidedPort»</code> an <code>State Management</code> mit Realisierungsbeziehung (Interface-Implementierung).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Service Interface <code>UpdateRequest</code>:</strong></li>\n<li>Stereotypen: <code>«aapAraComServiceInterface»</code>, <code>«aapInterface»</code>. Bindung erfolgt über die IPC-Transportschicht von <code>ara::com</code>.</li>\n<li>Methodenspezifische Stereotypen: <code>«aapAccessControlled»</code> (Absicherung über Identity and Access Management / IAM), <code>«aapServiceMethod»</code>.</li>\n<li>Methoden:</li>\n<li><code>RequestUpdateSession()</code>: Beantragt die exklusive Berechtigung zur Durchführung einer Update-Sitzung beim State Management.</li>\n<li><code>PrepareUpdate()</code>: Weist SM an, betroffene <code>FunctionGroups</code> bzw. Software-Cluster in einen update-fähigen Ruhezustand zu überführen.</li>\n<li><code>VerifyUpdate()</code>: Beauftragt SM mit der Funktions- und Integritätsprüfung nach Aktivierung des neuen Softwarestands.</li>\n<li><code>PrepareRollback()</code>: Signalisiert SM die Einleitung der Rückfallebene bei fehlgeschlagener Verifikation oder Update-Abbruch.</li>\n<li><code>ResetMachine()</code>: Fordert einen deterministischen Warmstart/Reboot der Machine an, um neue Partitionen/Softwarestände über das Execution Management zu mounten/starten.</li>\n<li><code>StopUpdateSession()</code>: Beendet die Update-Sitzung und versetzt die Machine zurück in den regulären Betriebsmodus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Session-Initialisierung (Trigger: Eingehendes Software-Paket):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>UCM Subordinate</code> ruft synchron/asynchron <code>RequestUpdateSession()</code> via <code>ara::com</code>.</li>\n<li><em>State Management</em> prüft globale System-Preconditions (z. B. Fahrzeugstillstand, Klemmenstatus, Diagnosemodus) und quittiert oder verweigert die Sitzung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung (Staging Phase):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Transfer/Extrahieren der Software-Cluster ruft UCM <code>PrepareUpdate()</code>.</li>\n<li>SM stoppt bzw. degradiert abhängige Applikationsprozesse über das <em>Execution Management</em> (<code>ara::exec</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Neustart:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Vorbereitung triggert UCM <code>ResetMachine()</code>.</li>\n<li>SM initiiert den kontrollierten Machine-State-Wechsel (Reboot/Shutdown).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verifikation & Abschluss / Rollback:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach dem Hochlauf veranlasst UCM über <code>VerifyUpdate()</code> die Verifikationsphase.</li>\n<li><em>Erfolgspfad:</em> SM meldet stabile Prozesszustände; UCM ruft <code>StopUpdateSession()</code>, womit die neue Version persistent geschaltet wird.</li>\n<li><em>Fehlerpfad:</em> Timeout oder Fehlfunktion; UCM initiiert <code>PrepareRollback()</code>, gefolgt von <code>ResetMachine()</code>, um den vorherigen Softwarestand zu reaktivieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Access Control & IAM (SWS / Manifeste):</strong> Da das Interface mit <code>«aapAccessControlled»</code> annotiert ist, muss im <em>Service Instance Manifest</em> und <em>Execution Manifest</em> ein entsprechendes <code>Grant</code> für den UCM-Prozess konfiguriert sein. Nicht autorisierte Aufrufe werden vom <code>ara::com</code>/IAM-Layer mit Security-Fehlern abgewiesen.</li>\n<li><strong>Plattform-Zustandsverantwortung:</strong> Applikations- und UCM-Entwickler dürfen keine direkten OS-Reboots (z. B. POSIX <code>reboot()</code>, <code>kill()</code>) aufrufen. Der Maschinenzustand darf ausschließlich deklarativ über SM und dessen Anbindung an <code>Execution Management</code> gewechselt werden.</li>\n<li><strong>Fehlerbehandlung (<code>ara::core::Result</code>):</strong> Sämtliche Methodenaufrufe erfordern robuste Auswertung von Rückgabecodes / Exceptions (insb. <code>UcmErrorDomain</code> bzw. <code>SmErrorDomain</code>). Ein Ablehnen von <code>RequestUpdateSession()</code> muss von UCM an das externe Diagnose- bzw. OTA-Backend propagiert werden (z. B. NRC <code>ConditionsNotCorrect</code>).</li>\n<li><strong>Daemon-Abhängigkeit:</strong> <code>State Management</code> läuft als nativer Plattform-Daemon. Startreihenfolgen und IPC-Verbindungsaufbau via <code>ara::com</code> müssen über das <em>Execution Manifest</em> so synchronisiert sein, dass <code>UpdateRequest</code> vor Beginn jeglicher UCM-Aktivitäten bindbar ist.</li>\n</ul>"}, {"id": "FIG-f80412a749129611", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm mit Service-Interface-Spezifikation (AUTOSAR Adaptive Platform Modellierung).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (R21-11), Functional Cluster <em>Update and Configuration Management (UCM)</em> in Interaktion mit <em>State Management (SM)</em>.</li>\n<li><strong>Technischer Zweck:</strong> Entkopplung der Update-Orchestrierung von der Systemzustandskontrolle. Das UCM (hier in der Rolle des <em>UCM Subordinate</em>) führt Software-Updates nicht eigenmächtig auf Prozessebene aus, sondern steuert den Lebenszyklus und die Ausführungsmodi der Machine über das servicifizierte Interface <code>UpdateRequest</code>, welches vom <em>State Management</em> bereitgestellt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Komponenten:</strong></li>\n<li><code>Update and Configuration Management</code> (<code>«aapFunctionalCluster»</code>, Ausprägung: <code>daemon-based</code>): Zentraler Plattform-Daemon zur Koordination und Ausführung von Software- und Konfigurationsaktualisierungen; agiert als Service-Consumer (Client).</li>\n<li><code>State Management</code> (<code>«aapFunctionalCluster»</code>, Ausprägung: <code>daemon-based</code>): Zentraler System-Daemon zur Koordination von Funktionsgruppen (<code>FunctionGroupState</code>), Maschinenmodi und Prozess-Lebenszyklen; agiert als Service-Provider (Server).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Ports & Bindungen:</strong></li>\n<li>Client-Port: <code>«aapRequiredPort»</code> an <code>Update and Configuration Management</code> mit Abhängigkeitsbeziehung (<code>«use»</code>) auf das Service-Interface.</li>\n<li>Server-Port: <code>«aapProvidedPort»</code> an <code>State Management</code> mit Realisierungsbeziehung (Interface-Implementierung).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Service Interface <code>UpdateRequest</code>:</strong></li>\n<li>Stereotypen: <code>«aapAraComServiceInterface»</code>, <code>«aapInterface»</code>. Bindung erfolgt über die IPC-Transportschicht von <code>ara::com</code>.</li>\n<li><strong>Service Fields (<code>«aapAccessControlled, aapServiceField»</code>):</strong></li>\n<li><code>ResetMachineNotifier</code>: Asynchrones Benachrichtigungsfeld / Event zur Signalisierung des Machine-Reset-Status (z. B. erfolgreicher Neustart <code>kSuccessful</code> nach Ausführung von <code>ResetMachine()</code>).</li>\n<li><strong>Service Methods (<code>«aapAccessControlled, aapServiceMethod»</code>):</strong></li>\n<li><code>RequestUpdateSession()</code>: Beantragt die exklusive Berechtigung zur Durchführung einer Update-Sitzung beim State Management.</li>\n<li><code>PrepareUpdate()</code>: Weist SM an, betroffene <code>FunctionGroups</code> bzw. Software-Cluster in einen update-fähigen Ruhezustand zu überführen.</li>\n<li><code>VerifyUpdate()</code>: Beauftragt SM mit der Funktions- und Integritätsprüfung nach Aktivierung des neuen Softwarestands.</li>\n<li><code>PrepareRollback()</code>: Signalisiert SM die Einleitung der Rückfallebene bei fehlgeschlagener Verifikation oder Update-Abbruch.</li>\n<li><code>ResetMachine()</code>: Fordert einen deterministischen Warmstart/Reboot der Machine an, um neue Partitionen/Softwarestände über das Execution Management zu mounten/starten.</li>\n<li><code>StopUpdateSession()</code>: Beendet die Update-Sitzung und versetzt die Machine zurück in den regulären Betriebsmodus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Session-Initialisierung (Trigger: Eingehendes Software-Paket):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Update and Configuration Management</code> (UCM) ruft <code>RequestUpdateSession()</code> via <code>ara::com</code> auf.</li>\n<li><code>State Management</code> (SM) prüft globale System-Preconditions (z. B. Fahrzeugzustand, Diagnosemodus) und bestätigt oder verweigert die Sitzung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung (Staging-Phase):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Transfer und Vorbereiten der Software-Cluster ruft UCM <code>PrepareUpdate()</code> auf.</li>\n<li>SM überführt betroffene Funktionsgruppen und Applikationsprozesse über das <em>Execution Management</em> (<code>ara::exec</code>) in einen sicheren bzw. inaktiven Zustand.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung, Neustart & Benachrichtigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>UCM fordert über <code>ResetMachine()</code> einen kontrollierten Warmstart/Reboot der Machine an.</li>\n<li>SM koordiniert das Herunterfahren und den Neustart der Maschine.</li>\n<li>Nach dem Wiederhochlauf signalisiert SM über das Service-Field <code>ResetMachineNotifier</code> asynchron das Ergebnis des Neustarts (z. B. <code>kSuccessful</code>), sodass UCM den Update-Ablauf an der unterbrochenen Stelle fortsetzen kann.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verifikation & Abschluss / Rollback:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>UCM veranlasst über <code>VerifyUpdate()</code> die Funktions- und Integritätsprüfung des neuen Softwarestands durch SM.</li>\n<li>Bei erfolgreicher Prüfung beendet UCM die Sitzung via <code>StopUpdateSession()</code>.</li>\n<li>Schlägt die Verifikation fehl oder bricht das Update ab, veranlasst UCM über <code>PrepareRollback()</code> die Rückführung auf den vorherigen Softwarestand.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Schnittstellenerweiterung:</strong></li>\n<li>Das Interface <code>UpdateRequest</code> spezifiziert ab R24-11 neben den Service-Methoden explizit das Service-Field <code>ResetMachineNotifier</code>. Implementierungen von State Management (Server) und UCM (Client) müssen dieses Feld VFB- und <code>ara::com</code>-konform bereitstellen bzw. abonnieren.</li>\n<li><strong>IAM & Zugriffskontrolle (<code>«aapAccessControlled»</code>):</strong></li>\n<li>Sowohl die Service-Methoden als auch das Field <code>ResetMachineNotifier</code> unterliegen der Zugriffskontrolle über das <em>Identity and Access Management</em> (IAM). In den Deployment-Manifesten müssen Client- und Server-Rechte für Methodenaufrufe und Event-Notifizierungen explizit konfiguriert werden.</li>\n<li><strong>Asynchrone Zustandsübergänge & Persistenz:</strong></li>\n<li>Durch den Maschinen-Reset wird der Prozesskontext von UCM und SM unterbrochen. UCM muss seinen internen Zustand vor <code>ResetMachine()</code> persistent ablegen (<code>ara::per</code>) und sich nach dem Wiederanlauf am Notifier des State Managements registrieren, um die Bestätigung (<code>ResetMachineNotifier</code>) für den Phasenübergang zur Verifikation zu empfangen.</li>\n</ul>"}], "trans": [{"from": "FIG-4143f759f4069d9a", "to": "FIG-cb8823e6e5b28f91", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cb8823e6e5b28f91", "to": "FIG-eb368619d39cb66b", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Client-Komponente (<code>Update and Configuration Management</code>):</strong> Ersetzung des vorherigen Bezeichners <code>UCM Subordinate</code> durch das standardisierte funktionale Cluster <code>«aapFunctionalCluster» Update and Configuration Management</code> mit der Ausprägung <code>daemon-based</code>.</li>\n</ul>"}, {"from": "FIG-eb368619d39cb66b", "to": "FIG-f80412a749129611", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Service-Interface <code>UpdateRequest</code>:</strong> Ergänzung eines neuen Service-Field-Bereichs (<code>«aapAccessControlled, aapServiceField»</code>) mit dem Feld <code>+ ResetMachineNotifier</code> oberhalb der Service-Methoden.</li>\n</ul>"}]};
